<?php
require_once __DIR__ . '/../../config/config.php';
require_roles(['ADMIN', 'HR']);
$pdo = db();
$search = trim((string) ($_GET['q'] ?? '')); $page = max(1, (int) ($_GET['page'] ?? 1)); $perPage = 8;
$filters = ['department_id' => filter_input(INPUT_GET, 'department_id', FILTER_VALIDATE_INT) ?: null, 'position_id' => filter_input(INPUT_GET, 'position_id', FILTER_VALIDATE_INT) ?: null, 'branch_id' => filter_input(INPUT_GET, 'branch_id', FILTER_VALIDATE_INT) ?: null, 'employment_status' => post_value('employment_status') ?: trim((string) ($_GET['employment_status'] ?? ''))];
$where = []; $params = [];
if ($search !== '') { $where[] = '(e.employee_number LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR e.email LIKE ?)'; array_push($params, "%$search%", "%$search%", "%$search%", "%$search%"); }
foreach (['department_id','position_id','branch_id'] as $field) if ($filters[$field]) { $where[] = 'e.' . $field . '=?'; $params[] = $filters[$field]; }
if ($filters['employment_status'] !== '') { $where[] = 'e.employment_status=?'; $params[] = $filters['employment_status']; }
$condition = $where ? ' WHERE ' . implode(' AND ', $where) : '';
$count = $pdo->prepare('SELECT COUNT(*) FROM employees e' . $condition); $count->execute($params); $total = (int) $count->fetchColumn(); $pages = max(1, (int) ceil($total / $perPage)); $page = min($page, $pages); $offset = ($page - 1) * $perPage;
$query = $pdo->prepare('SELECT e.*,d.name department_name,p.name position_name,b.name branch_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN positions p ON p.id=e.position_id LEFT JOIN branches b ON b.id=e.branch_id' . $condition . ' ORDER BY e.last_name,e.first_name LIMIT ' . $perPage . ' OFFSET ' . $offset); $query->execute($params); $employees = $query->fetchAll();
$departments = $pdo->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll(); $positions = $pdo->query('SELECT id,name FROM positions WHERE is_active=1 ORDER BY name')->fetchAll(); $branches = $pdo->query('SELECT id,name FROM branches WHERE is_active=1 ORDER BY name')->fetchAll();
$pageTitle = 'Employees'; require __DIR__ . '/../../includes/header.php';
?><div class="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-7"><div><p class="text-sm text-slate-500">Core HCM master records</p><h1 class="font-display text-3xl font-bold mt-1">Employees</h1></div><a href="create.php" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">+ Add employee</a></div><form class="bg-white border border-slate-200 rounded-xl p-4 mb-6 grid sm:grid-cols-2 lg:grid-cols-6 gap-3"><input name="q" value="<?= e($search) ?>" placeholder="Search name or ID" class="field !mt-0 lg:col-span-2"><select name="department_id" class="field !mt-0"><option value="">All departments</option><?php foreach($departments as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)$filters['department_id']===(string)$item['id']?'selected':'' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select><select name="position_id" class="field !mt-0"><option value="">All positions</option><?php foreach($positions as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)$filters['position_id']===(string)$item['id']?'selected':'' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select><select name="branch_id" class="field !mt-0"><option value="">All branches</option><?php foreach($branches as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)$filters['branch_id']===(string)$item['id']?'selected':'' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select><select name="employment_status" class="field !mt-0"><option value="">All statuses</option><?php foreach(['Active','Probationary','On Leave','Separated'] as $status): ?><option <?= $filters['employment_status']===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select><button class="rounded-lg bg-slate-900 px-4 py-2 text-sm font-bold text-white">Filter</button></form><div class="bg-white border border-slate-200 rounded-xl overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-400"><tr><th class="px-5 py-4">Employee</th><th class="px-5 py-4">Department</th><th class="px-5 py-4">Position</th><th class="px-5 py-4">Branch</th><th class="px-5 py-4">Status</th><th class="px-5 py-4">Date hired</th><th class="px-5 py-4">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($employees as $employee): ?><tr><td class="px-5 py-4"><b><?= e($employee['first_name'].' '.$employee['last_name']) ?></b><p class="text-xs text-slate-400"><?= e($employee['employee_number']) ?></p></td><td class="px-5 py-4"><?= e($employee['department_name'] ?? '—') ?></td><td class="px-5 py-4"><?= e($employee['position_name'] ?? '—') ?></td><td class="px-5 py-4"><?= e($employee['branch_name'] ?? '—') ?></td><td class="px-5 py-4"><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700"><?= e($employee['employment_status']) ?></span></td><td class="px-5 py-4"><?= e($employee['date_hired'] ?? '—') ?></td><td class="px-5 py-4 whitespace-nowrap"><a class="font-bold text-teal-700" href="view.php?id=<?= e($employee['id']) ?>">View</a><a class="ml-3 font-bold text-slate-600" href="edit.php?id=<?= e($employee['id']) ?>">Edit</a><a class="ml-3 font-bold text-slate-600" href="lifecycle.php?id=<?= e($employee['id']) ?>">Lifecycle</a><a class="ml-3 font-bold text-slate-600" href="../employee-records/index.php?employee_id=<?= e($employee['id']) ?>">Records</a></td></tr><?php endforeach; ?></tbody></table><?php if (!$employees): ?><p class="p-10 text-center text-slate-500">No employees match these filters.</p><?php endif; ?></div><div class="mt-4 flex justify-between text-sm text-slate-500"><span>Showing <?= e($total ? $offset + 1 : 0) ?>–<?= e(min($offset + $perPage, $total)) ?> of <?= e($total) ?></span><div class="space-x-2"><?php if($page>1): ?><a class="font-bold text-teal-700" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif; ?><?php if($page<$pages): ?><a class="font-bold text-teal-700" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div></div><?php require __DIR__ . '/../../includes/footer.php';